helpers:
fn frontier_step_reference(afterstate:&PoolV1PairVerifiedAfterstateV1,mut output:[u8;688],level:usize)->[u8;688] {
 let start=48+32*level;
 output[start..start+32].copy_from_slice(&encode_digest_canonical(&afterstate.next_frontier[level]));
 output
}
fn frontier_owned_reference(afterstate:&PoolV1PairVerifiedAfterstateV1,mut output:[u8;688])->[u8;688] {
 for level in 0..20 {output=frontier_step_reference(afterstate,output,level);}
 output
}
